// GERADO por scripts/gerar-manuais.mts — não editar à mão. Fonte: docs/manuais/parceiros.md
export const html: string = "<h2 id=\"visão-geral\">Visão geral</h2>\n<p><strong>Parceiro</strong> é todo mundo com quem a empresa tem relação comercial: <strong>clientes</strong> (quem aluga), <strong>fornecedores</strong> (gráfica, engenheiro, papelaria, manutenção, sublocação…) e <strong>transportadoras</strong>. Um mesmo cadastro pode ter mais de um papel. Uma gráfica que também aluga equipamento, por exemplo, é cliente e fornecedor ao mesmo tempo.</p>\n<p>O cadastro é <strong>um só para a Rentech e a AlfaLight</strong>, e o <strong>CPF ou CNPJ é a chave</strong>: não existem dois cadastros com o mesmo documento.</p>\n<div class=\"tabela\"><table>\n<thead>\n<tr>\n<th>Onde o cadastro é usado</th>\n<th>Precisa estar marcado como</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Reserva, proposta, contrato e nota fiscal (o endereço principal sai nos documentos)</td>\n<td>Cliente</td>\n</tr>\n<tr>\n<td>Portal do Cliente (entra com o e-mail do cadastro ou de um contato)</td>\n<td>Cliente</td>\n</tr>\n<tr>\n<td>Ordem de Pagamento e contas a pagar</td>\n<td>Fornecedor</td>\n</tr>\n<tr>\n<td>Sublocação (parceiro que nos aluga equipamento)</td>\n<td>Fornecedor</td>\n</tr>\n<tr>\n<td>Agenda de contatos: achar a gráfica, o engenheiro, a papelaria…</td>\n<td>Fornecedor + Ramo / serviço</td>\n</tr>\n</tbody></table></div>\n<p>As telas deste manual usam cadastros fictícios (GRÁFICA EXEMPLO, PAPELARIA EXEMPLO). Nada foi salvo para as fotos.</p>\n<h2 id=\"onde-fica-e-como-achar-um-parceiro\">Onde fica e como achar um parceiro</h2>\n<p><strong>Comercial → Parceiros</strong>, aba <strong>Parceiros</strong>.</p>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Comercial → Parceiros: busca, filtro e o botão + Novo cliente / fornecedor\" loading=\"lazy\" /><span class=\"legenda\">Comercial → Parceiros: busca, filtro e o botão + Novo cliente / fornecedor</span></span></p>\n<ul>\n<li><strong>Busca:</strong> por nome, nome fantasia, CNPJ, CPF ou cidade. Espaço vale como &quot;qualquer coisa no meio&quot;: &quot;EXEMPLO MANUAL&quot; acha &quot;EXEMPLO (MANUAL)&quot;. A busca diferencia acento: &quot;GRAFICA&quot; não acha &quot;GRÁFICA&quot;. Na dúvida, busque um pedaço sem acento (&quot;GRAF&quot;) ou use o filtro de ramo.</li>\n<li><strong>Filtro de papel:</strong> Todos, Clientes ou Fornecedores.</li>\n<li><strong>Filtro de ramo:</strong> ao lado do filtro de papel, &quot;Todos os ramos&quot; ou um ramo. Para achar as gráficas, escolha <strong>Fornecedores</strong> + <strong>Gráfica</strong>.</li>\n<li><strong>Em cada linha:</strong> código, nome (com as etiquetas de ramo embaixo), CNPJ/CPF, cidade, telefone e o <strong>contato principal</strong> (nome e telefone), além de se é cliente e se é fornecedor.</li>\n<li><strong>Selo SISTEMA:</strong> o cadastro foi feito aqui no sistema. Sem o selo, ele veio do P2S (ver &quot;Cadastros que vieram do P2S&quot;).</li>\n<li><strong>Clicar na linha</strong> abre o cadastro. A lupa 🔍 mostra todos os campos guardados, inclusive os que vieram do P2S.</li>\n</ul>\n<h2 id=\"cadastrar-um-fornecedor\">Cadastrar um fornecedor</h2>\n<p>Exemplo: uma gráfica nova.</p>\n<ol>\n<li>Clique em <strong>+ Novo cliente / fornecedor</strong>.</li>\n<li><strong>Tipo:</strong> Pessoa jurídica (empresa) ou Pessoa física (um engenheiro autônomo, por exemplo).</li>\n<li><strong>CNPJ ou CPF.</strong> Ao sair do campo, o sistema avisa na hora se o documento já está cadastrado.</li>\n<li><strong>Buscar na Receita</strong> (só para CNPJ): preenche razão social, nome fantasia, endereço, telefone e e-mail, e mostra a situação na Receita. Se o CNPJ não estiver ATIVO, aparece um aviso em vermelho. Confira os dados antes de salvar.</li>\n<li>Marque <strong>Fornecedor</strong> e desmarque <strong>Cliente</strong> se ele não for alugar com a gente.</li>\n<li><strong>Ramo / serviço:</strong> clique no ramo, por exemplo <strong>Gráfica</strong> (ver a seção &quot;Ramo / serviço&quot;).</li>\n<li><strong>Telefones e e-mails:</strong> o telefone e o e-mail principais. Use &quot;Outro e-mail&quot; para o financeiro ou para a nota fiscal.</li>\n<li><strong>Contatos:</strong> as pessoas com quem você fala, como o atendente ou o responsável pelo orçamento (ver &quot;Contatos e outros endereços&quot;).</li>\n<li><strong>Salvar.</strong> O cadastro ganha um código da faixa 900000 (os do P2S têm outra numeração) e o selo SISTEMA.</li>\n</ol>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Novo fornecedor: CNPJ buscado na Receita, Fornecedor marcado e o ramo Gráfica\" loading=\"lazy\" /><span class=\"legenda\">Novo fornecedor: CNPJ buscado na Receita, Fornecedor marcado e o ramo Gráfica</span></span></p>\n<p><strong>Pessoa física</strong> (engenheiro, eletricista, consultor autônomo): o CPF é obrigatório e precisa ser válido. Não existe &quot;Buscar na Receita&quot; para CPF, então preencha nome, telefone e endereço à mão.</p>\n<h2 id=\"cadastrar-um-cliente\">Cadastrar um cliente</h2>\n<p>O passo a passo é o mesmo, com três diferenças:</p>\n<ol>\n<li>Deixe <strong>Cliente</strong> marcado. Só cliente aparece na busca da reserva.</li>\n<li><strong>Endereço principal:</strong> é o que sai na proposta, no contrato e na nota fiscal. Ao digitar o CEP e clicar em <strong>Buscar</strong>, o endereço vem sozinho.</li>\n<li><strong>Carteira do vendedor:</strong> escolha o vendedor responsável. O vendedor só vê e atende os clientes da carteira dele. Sem carteira, o cliente entra na carteira de quem fizer a primeira ficha.</li>\n</ol>\n<p>O <strong>e-mail principal</strong>, ou o e-mail de um contato, é o que o cliente usa para entrar no <strong>Portal do Cliente</strong> e acompanhar as locações.</p>\n<h2 id=\"ramo--serviço\">Ramo / serviço</h2>\n<p>O ramo diz <strong>o que o parceiro faz para nós</strong>. Ele serve para montar a agenda de fornecedores: &quot;quem são as gráficas?&quot;, &quot;qual engenheiro já usamos?&quot;.</p>\n<ul>\n<li>Aparece no cadastro quando o parceiro é <strong>fornecedor</strong> ou <strong>transportadora</strong>.</li>\n<li>Clique para marcar e de novo para desmarcar. Pode marcar <strong>mais de um</strong> (uma gráfica que também faz brindes, por exemplo).</li>\n<li><strong>Ramo que não está na lista:</strong> escreva no campo &quot;Outro ramo&quot; e clique em <strong>+ Novo ramo</strong>. Ele é criado e já fica marcado. Se o nome já existir, mesmo escrito com outras maiúsculas e minúsculas, o sistema reaproveita o ramo existente.</li>\n<li><strong>Ramos que já vêm na lista:</strong> Alimentação, Brindes e uniformes, Combustível e veículos, Contabilidade, Elétrica, Engenharia, Frete e transporte, Gráfica, Informática / TI, Jurídico, Limpeza e conservação, Manutenção predial, Material de escritório, Segurança e Sublocação de equipamentos.</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Ramo / serviço: Gráfica marcada e um ramo novo criado na hora\" loading=\"lazy\" /><span class=\"legenda\">Ramo / serviço: Gráfica marcada e um ramo novo criado na hora</span></span></p>\n<p>O ramo <strong>pode ser marcado também nos cadastros que vieram do P2S</strong>. A sincronização com o P2S não apaga o que você marcar.</p>\n<h2 id=\"contatos-e-outros-endereços\">Contatos e outros endereços</h2>\n<p><strong>Contatos</strong> (botão <strong>+ Contato</strong>): uma linha por pessoa, com nome, cargo ou área, telefone, e-mail e a marcação de <strong>principal</strong>. O principal é o que aparece na lista de Parceiros. Só um contato pode ser o principal: marcar outro desmarca o anterior.</p>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Dois contatos da gráfica: orçamentos (principal) e financeiro\" loading=\"lazy\" /><span class=\"legenda\">Dois contatos da gráfica: orçamentos (principal) e financeiro</span></span></p>\n<p><strong>Outros endereços</strong> (botão <strong>+ Endereço</strong>): entrega, cobrança, depósito…, cada um com tipo, endereço, cidade, UF, CEP e observação. O endereço principal continua sendo o da seção &quot;Endereço principal&quot;.</p>\n<p><strong>Observações:</strong> texto livre no fim do cadastro, por exemplo &quot;pedir orçamento com 3 dias de antecedência&quot;.</p>\n<h2 id=\"bloquear-um-parceiro\">Bloquear um parceiro</h2>\n<p>Em <strong>Situação</strong>, escolha <strong>Bloqueado</strong> e escreva o <strong>motivo</strong>, que é obrigatório. O cadastro continua existindo, com o histórico, e o motivo fica registrado para quem abrir o cadastro. Para desbloquear, volte para <strong>Ativo</strong>.</p>\n<h2 id=\"cadastros-que-vieram-do-p2s\">Cadastros que vieram do P2S</h2>\n<p>Os parceiros cadastrados no P2S chegam ao sistema pela sincronização das <strong>11h e 17h</strong>, ou na hora pelo botão <strong>Sincronizar agora</strong> da mesma tela.</p>\n<p><strong>Enquanto o P2S for oficial:</strong></p>\n<ul>\n<li>O cadastro do P2S fica <strong>só para leitura</strong>. Para mudar nome, documento, endereço, telefone ou contatos, altere no P2S. A mudança chega aqui na próxima sincronização.</li>\n<li>Mesmo assim, aqui dá para mudar a <strong>carteira do vendedor</strong> (clientes) e o <strong>Ramo / serviço</strong> (fornecedores). Nesses cadastros, o botão de salvar vira &quot;Salvar ramo&quot; ou &quot;Salvar carteira e ramo&quot;.</li>\n<li><strong>Cadastrou aqui e depois alguém cadastrou o mesmo CPF/CNPJ no P2S?</strong> A sincronização <strong>adota</strong> o cadastro daqui em vez de criar outro. Ele mantém o mesmo número e passa a seguir o P2S.</li>\n</ul>\n<p><span class=\"figura\"><img src=\"data:image/png;base64,\" alt=\"Cadastro do P2S: tudo só leitura, menos o ramo (e a carteira, quando é cliente)\" loading=\"lazy\" /><span class=\"legenda\">Cadastro do P2S: tudo só leitura, menos o ramo (e a carteira, quando é cliente)</span></span></p>\n<p><strong>Depois da virada da chave:</strong> o sistema vira a origem de todos os cadastros, tudo pode ser editado aqui e a sincronização de parceiros para.</p>\n<h2 id=\"funcionário-que-é-cliente-ou-fornecedor\">Funcionário que é cliente ou fornecedor</h2>\n<p>Para marcar que um funcionário também é cliente ou fornecedor, use a <strong>Ficha do Funcionário</strong> (RH), no painel <strong>💼 Papéis comerciais</strong>, e não esta tela. O CPF da ficha é a chave: se já existe um parceiro com aquele CPF, ele é usado; se não existe, o sistema cria o cadastro com os dados da ficha. Detalhes no manual <strong>Cadastros do sistema</strong>.</p>\n<h2 id=\"dúvidas-comuns\">Dúvidas comuns</h2>\n<ul>\n<li><strong>&quot;Já existe um cadastro com este CNPJ/CPF&quot;.</strong> O parceiro já está no sistema, com o nome e o código mostrados na mensagem. Feche, busque pelo documento na lista e edite o cadastro existente. Se ele for só cliente e agora também for fornecedor, marque <strong>Fornecedor</strong> nele.</li>\n<li><strong>Não consigo editar os campos.</strong> O cadastro veio do P2S e o P2S ainda é oficial. Altere no P2S, ou mude só o ramo e a carteira aqui.</li>\n<li><strong>O cliente não aparece na reserva.</strong> Confira se ele está marcado como <strong>Cliente</strong>.</li>\n<li><strong>A Receita não preencheu.</strong> O serviço de consulta pode estar fora do ar. Preencha à mão e tente &quot;Buscar na Receita&quot; mais tarde, se quiser conferir.</li>\n<li><strong>O fornecedor não tem CNPJ</strong> (autônomo). Cadastre como <strong>Pessoa física</strong>, com o CPF.</li>\n<li><strong>Quero ver todas as gráficas com telefone.</strong> Na lista, escolha <strong>Fornecedores</strong> + o ramo <strong>Gráfica</strong>. O telefone e o contato principal aparecem na coluna Telefone.</li>\n</ul>\n";
export const sumario: { id: string; texto: string }[] = [{"id":"visão-geral","texto":"Visão geral"},{"id":"onde-fica-e-como-achar-um-parceiro","texto":"Onde fica e como achar um parceiro"},{"id":"cadastrar-um-fornecedor","texto":"Cadastrar um fornecedor"},{"id":"cadastrar-um-cliente","texto":"Cadastrar um cliente"},{"id":"ramo--serviço","texto":"Ramo / serviço"},{"id":"contatos-e-outros-endereços","texto":"Contatos e outros endereços"},{"id":"bloquear-um-parceiro","texto":"Bloquear um parceiro"},{"id":"cadastros-que-vieram-do-p2s","texto":"Cadastros que vieram do P2S"},{"id":"funcionário-que-é-cliente-ou-fornecedor","texto":"Funcionário que é cliente ou fornecedor"},{"id":"dúvidas-comuns","texto":"Dúvidas comuns"}];
